<script setup lang="ts">
// Ambient cycle and flowing-path implementation copied from NJUAnimatedEveNet.vue.
// The graph is fully visible from entry; there are no progressive click states.
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {animate} from 'animejs'
import {useSlideContext} from '@slidev/client'
const props=defineProps<{kind:string}>(); const {$nav,$page,$renderContext}=useSlideContext()
const ambient=reactive({cycle:0});const reduced=ref(false),hidden=ref(false);let loop:any,media:MediaQueryList
const running=computed(()=>$nav.value.currentPage===$page.value&&$renderContext.value==='slide'&&!reduced.value&&!hidden.value)
function syncLoop(){loop?.cancel();if(running.value)loop=animate(ambient,{cycle:{from:ambient.cycle,to:ambient.cycle+1},duration:2500,ease:'linear',loop:true})}
function visibility(){hidden.value=document.hidden}function preference(){reduced.value=media.matches||location.search.includes('static')}
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');media.addEventListener('change',preference);document.addEventListener('visibilitychange',visibility);preference();visibility();syncLoop()});watch(running,syncLoop);onBeforeUnmount(()=>{loop?.cancel();media?.removeEventListener('change',preference);document.removeEventListener('visibilitychange',visibility)})
const colors=['#77c9ff','#f0c36e','#baa5ff','#70dcb2','#f69cab']
const definitions:any={
workflow:{nodes:[[10,95,150,96,'Generation','Beam / hard process',0],[212,95,150,96,'DSimu','Geant4 transport',1],[414,95,150,96,'DEvent','Truth + hit records',2],[616,95,235,96,'DAna','Digitisation / reconstruction',3],[622,247,230,67,'Physics analysis','Selections + normalisation',4],[213,247,350,67,'DDis event display','Inspect geometry, truth and response',0]],edges:['M160 143 H212','M362 143 H414','M564 143 H616','M733 191 V247','M489 191 V224 H389 V247']},
filter:{nodes:[[15,70,230,100,'Stage 0','Primary track only',0],[325,70,230,100,'Stage 1','Secondaries in the ROI',1],[635,70,230,100,'Stage 2','Release remaining tracks',3],[15,245,230,68,'Reject early','Primary filter failed',4],[325,245,230,68,'Reject early','Required interaction absent',4],[635,245,230,68,'Write selected event','Complete retained transport',2]],edges:['M245 120 H325','M555 120 H635','M130 170 V245','M440 170 V245','M750 170 V245']},
digit:{nodes:[[15,110,158,100,'Energy deposit','Geant4 hits',0],[232,110,158,100,'Optical response','Full transport / LUT',1],[449,110,158,100,'SiPM + ADC','Recovery, noise, sampling',2],[666,110,195,100,'Calibrated energy','Cell response + clusters',3]],edges:['M173 160 H232','M390 160 H449','M607 160 H666']},
acts:{nodes:[[10,75,215,95,'DSS event + geometry','Strip pairs / field map',0],[330,75,220,95,'ACTS conversion','Surfaces / source links',1],[650,75,220,95,'Truth-smeared seeds','Reference configuration',4],[650,240,220,80,'Combinatorial KF','Track candidates',2],[330,240,220,80,'Tracks + vertices','Parameters / fit quality',3],[10,240,215,80,'ECAL seed interface','Extrapolated impact points',0]],edges:['M225 122 H330','M550 122 H650','M760 170 V240','M650 280 H550','M330 280 H225']},
tracking:{nodes:[[15,110,165,100,'Strip measurements','Stereo coordinate pairs',0],[238,110,165,100,'Track finding','Candidate hit association',1],[461,110,165,100,'Track fitting','Field + material + errors',2],[684,110,180,100,'Physics observables','Momentum / multiplicity',3]],edges:['M180 160 H238','M403 160 H461','M626 160 H684']},
model:{nodes:[[315,115,250,95,'DEvent','Shared ROOT event record',1],[15,15,220,70,'McParticle','Generated / transported truth',0],[15,140,220,70,'DStep','Transport-step information',0],[15,265,220,70,'SimulatedHit','Sensitive-detector deposits',2],[650,60,220,85,'CalorimeterHit','Detector response',3],[650,230,220,85,'ReconstructedParticle','Inferred particle objects',4]],edges:['M235 50 H270 V145 H315','M235 175 H315','M235 300 H270 V180 H315','M565 145 H610 V103 H650','M565 180 H610 V273 H650']}}
const graph=computed(()=>definitions[props.kind]||definitions.workflow)
</script>
<template><svg :class="kind" :viewBox="['digit','tracking'].includes(kind)?'0 70 880 180':'0 0 880 350'" class="flow-diagram" :aria-label="kind+' flow diagram'" role="img"><g v-for="(path,i) in graph.edges" :key="path"><path :d="path" fill="none" stroke="#6f859b" stroke-width="1.3"/><path :d="path" :stroke="colors[i%5]" fill="none" pathLength="100" stroke-dasharray="9 91" :stroke-dashoffset="-100*(ambient.cycle+i*.17)" stroke-width="3"/></g><g v-for="(n,i) in graph.nodes" :key="i"><rect :x="n[0]" :y="n[1]" :width="n[2]" :height="n[3]" rx="8" fill="#23262b" stroke="#718094" stroke-opacity=".5"/><path :d="`M${n[0]+16} ${n[1]} H${n[0]+n[2]-16}`" :stroke="colors[n[6]]" stroke-width="2"/><foreignObject :x="n[0]+9" :y="n[1]+15" :width="n[2]-18" :height="n[3]-17"><div xmlns="http://www.w3.org/1999/xhtml" class="node-text"><strong :style="{color:colors[n[6]]}">{{n[4]}}</strong><span>{{n[5]}}</span></div></foreignObject></g></svg></template>
<style scoped>.flow-diagram{display:block;width:100%;height:310px;overflow:visible}.node-text{text-align:center;font-family:'DM Sans',sans-serif;line-height:1.3}.node-text strong{display:block;font-size:19px;font-weight:600}.node-text span{display:block;font-size:14px;color:#bcc2cb;margin-top:8px}.flow-diagram.tracking .node-text strong{font-size:16px}.flow-diagram.tracking .node-text span{font-size:12px;margin-top:6px}</style>
